SELECT name, address_city, regexp_replace(ai_query('databricks-meta-llama-3-3-70b-instruct', concat('From this facility record, decide whether it offers dialysis. Quote the exact supporting sentence or null. Name: ', name, '. City: ', address_city, '. Procedures: ', coalesce(procedure,''), ' Capabilities: ', coalesce(capability,'')), responseFormat => '{"type":"json_schema","json_schema":{"name":"svc","schema":{"type":"object","properties":{"offers_dialysis":{"type":"string","enum":["yes","no","unclear"]},"evidence_quote":{"type":["string","null"]},"confidence":{"type":"number"}},"required":["offers_dialysis","evidence_quote","confidence"]},"strict":true}}'), '[\t\n]', ' ') AS verdict FROM databricks_virtue_foundation_dataset_dais_2026.virtue_foundation_dataset.facilities WHERE lower(procedure) LIKE '%dialysis%' LIMIT 2
